<?php
namespace App\Http\Controllers; use App\Models\Transaction; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class TransactionController extends Controller { public function index(Request $request,string $type){abort_unless(in_array($type,['sale','expense','transfer'],true),404);$types=$type==='transfer'?['transfer_in','transfer_out']:[$type];$transactions=Transaction::with('creator')->whereIn('type',$types)->latest('transaction_date')->latest('id')->paginate(30);return view('transactions.index',compact('transactions','type'));} public function store(Request $request){$data=$request->validate(['type'=>['required',Rule::in(['sale','expense','transfer_in','transfer_out'])],'transaction_date'=>'required|date','amount'=>'required|numeric|min:0.01|max:9999999999.99','category'=>'required|string|max:100','payment_method'=>'required|string|max:50','from_account'=>'nullable|string|max:100','to_account'=>'nullable|string|max:100','reference'=>'nullable|string|max:100','notes'=>'nullable|string|max:2000','receipt'=>'nullable|file|mimes:pdf,jpg,jpeg,png,webp|max:10240']);if($request->hasFile('receipt')){$data['receipt_path']=$request->file('receipt')->store('receipts/'.$data['transaction_date'],'public');$data['receipt_original_name']=$request->file('receipt')->getClientOriginalName();}unset($data['receipt']);$data['created_by']=$request->user()->id;Transaction::create($data);return back()->with('success','Transaction saved successfully.');} public function destroy(Request $request,Transaction $transaction){abort_unless($request->user()->canManageFinance(),403);$transaction->delete();return back()->with('success','Transaction deleted.');} }
